<script>
 import {outputState,queueTaskOutputs} from '../stores/output.svelte';import {downloadTaskOutputs,saveTaskOutputsAs} from '../services/task-output.ts';import {project} from '../stores/project.svelte';import Button from '../ui/Button.svelte';
 let {task}=$props();let error=$state(''),pending=$state(false),savedAs=$state(''),showFiles=$state(false),page=$state(0);const pageSize=25;const state=$derived(outputState.byId[task.id]);const count=$derived(task.outputs?.filter(output=>output.status==='ok').length||0);
 async function save(){pending=true;error='';try{if(project.currentId!==task.projectId)project.select(task.projectId);if(project.permission!=='granted')await project.authorizeDirectory();await queueTaskOutputs(task,true);}catch(e){error=e.message;}finally{pending=false;}}
 async function saveAs(){pending=true;error='';try{const result=await saveTaskOutputsAs(task);if(result?.saved)savedAs=result.name;}catch(e){error=e.message;}finally{pending=false;}}
 async function download(){pending=true;error='';try{await downloadTaskOutputs(task);}catch(e){error=e.message;}finally{pending=false;}}
</script>
{#if count}<div class="task-output">{#if task.undone}<p>处理已撤销；已保存文件保留。</p>{/if}<p role="status">{state?.state==='saved'?`已校验并写回 ${state.files.length} 个文件`:state?.state==='saving'?'正在校验并写回本机…':state?.state==='error'?state.error:'结果已保存在工作区，可下载或保存到已授权文件夹。'}</p><Button disabled={pending||state?.state==='saving'} onclick={save}>{state?.state==='saved'?'重新检查保存':'保存到文件夹'}</Button><Button disabled={pending} onclick={download}>{count>1?'下载结果 ZIP':'下载结果'}</Button><Button disabled={pending} onclick={saveAs}>{count>1?'另存为 ZIP':'另存为'}</Button>{#if savedAs}<p role="status">已校验并另存为：{savedAs}</p>{/if}<Button variant="subtle" aria-expanded={showFiles} onclick={()=>showFiles=!showFiles}>导出明细 {task.outputs.length}</Button>{#if showFiles}<div class="task-output-files">{#each task.outputs.slice(page*pageSize,(page+1)*pageSize) as output}<p><b>{output.name}</b> · {output.width} × {output.height} · {Math.ceil(output.bytes/1000)} KB · {output.status==='ok'?output.format?.toUpperCase()||'':'未达到导出要求'}</p>{/each}{#if task.outputs.length>pageSize}<div><Button disabled={page===0} onclick={()=>page--}>上一页</Button><span>{page+1} / {Math.ceil(task.outputs.length/pageSize)}</span><Button disabled={(page+1)*pageSize>=task.outputs.length} onclick={()=>page++}>下一页</Button></div>{/if}</div>{/if}{#if error}<p role="alert">{error}</p>{/if}</div>{/if}
<style>.task-output{margin-top:10px;font-size:12px;line-height:1.6}.task-output p{margin:4px 0 8px;overflow-wrap:anywhere}.task-output :global(button){margin:2px}.task-output [role=alert]{color:var(--danger)}.task-output-files{max-height:240px;overflow:auto;padding:8px 0}.task-output-files b{font-weight:500}.task-output-files>div{display:flex;align-items:center;gap:8px}</style>
